mapper.select:
SELECT member_id, email, name, member_type, org_reg_no, org_status, reject_reason, created_at FROM member WHERE member_type = 'ORGANIZATION'
AND org_status = #{status}
ORDER BY created_at DESC

mapper.update:
UPDATE member
SET org_status = #{status}, reject_reason = #{rejectReason}
WHERE member_id = #{memberId} AND member_type = 'ORGANIZATION'

UPDATE member
SET password = #{password}
WHERE email = #{email} AND deleted_at IS NULL

UPDATE member
SET point_balance = point_balance - #{amount}
WHERE member_id = #{memberId} AND point_balance >= #{amount}

UPDATE member
SET refresh = #{refresh}
WHERE email = #{email}
